  ls: async () => {
    const { stdout } = await run('docker', [
      'ps',
      '--filter',
      'label=io.swcode.urbo.instance',
      '--format',
      '{{.Label "io.swcode.urbo.instance"}}\t{{.Service}}\t{{.Status}}',
    ]);
    const byInstance = new Map();
    for (const line of stdout.split('\n').filter(Boolean)) {
      const [instance, service, status] = line.split('\t');
      if (!byInstance.has(instance)) {
        byInstance.set(instance, []);
      }
      byInstance.get(instance).push(`    ${service.padEnd(24)} ${status}`);
    }
    if (byInstance.size === 0) {
      console.log('No Urbo instances running.');
    } else {
      for (const [instance, lines] of byInstance) {
        console.log(`${instance}\n${lines.join('\n')}`);
      }
    }
    return 0;
  },
